def zip_dict(ks, vs):
    """
    Create a dictionary mapping each key from `ks` to the corresponding value from `vs`.
    Excess values in `vs` are ignored. If `vs` has fewer elements than `ks`,
    missing values are set to None.
    """
    result = {}
    for i, key in enumerate(ks):
        result[key] = vs[i] if i < len(vs) else None
    return result

